export function buildMenuTree(e){if(!Array.isArray(e))return[];const n=new Map,t=[];for(let r=0;r<e.length;r++){const s=e[r];s.parent||t.push(s);let c=n.get(s.parent);c||(c=[],n.set(s.parent,c)),c.push(s)}const r=t.slice(),s=new Set;for(;r.length;){const e=r.pop();if(s.has(e))continue;s.add(e);const t=n.get(e.id);e.children=t?t.slice():[];for(let n=0;n<e.children.length;n++)r.push(e.children[n])}return t}